/// Checks if a given number is even.
fn is_even(n: u32) -> bool {
    n % 2 == 0
}

/// Executes the is_even function for a given number.
fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

/// Checks if the provided array contains at least one even number.
fn is_product_even(arr: &Vec<u32>) -> bool {
    for &num in arr {
        if is_even(num) {
            return true;
        }
    }
    false
}

// Example usage
fn main() {
    let numbers = vec![1, 3, 5, 7, 8];
    let result = is_product_even(&numbers);
    println!("Does the array contain at least one even number? {}", result); // Should print true
}